describe('Username Availability Async Validation', () => {
  beforeEach(() => {
    cy.visit('/register');
  });

  it('should display success message when username is available', () => {
    cy.get('[data-testid="username-input"]').type('testuser123');
    cy.get('[data-testid="validate-button"]').click();
    cy.intercept('POST', '/api/validate-username').as('validateUsername');
    cy.wait('@validateUsername');

    cy.get('[data-testid="validation-status"]')
      .should('contain', 'Username is available');
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Username successfully registered');
    cy.get('[data-testid="username-input"]').should('have.value', 'testuser123');
  });

  it('should display error message when username is already taken', () => {
    cy.get('[data-testid="username-input"]').type('existinguser');
    cy.get('[data-testid="validate-button"]').click();
    cy.intercept('POST', '/api/validate-username').as('validateUsername');
    cy.wait('@validateUsername');

    cy.get('[data-testid="validation-status"]')
      .should('contain', 'Username is taken');
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Username is already in use');
    cy.get('[data-testid="username-input"]').should('have.value', 'existinguser');
  });

  it('should clear input when validation fails', () => {
    cy.get('[data-testid="username-input"]').type('invalidusername');
    cy.get('[data-testid="validate-button"]').click();
    cy.intercept('POST', '/api/validate-username').as('validateUsername');
    cy.wait('@validateUsername');

    cy.get('[data-testid="validation-status"]')
      .should('contain', 'Username is invalid');
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Username must be at least 6 characters long');
    cy.get('[data-testid="username-input"]').should('have.value', 'invalidusername');
  });
});
